using Aetheus.Back.Components.Pipelines;
using Aetheus.Back.Data;
using Aetheus.Back.Data.Entities;
using Aetheus.Back.Hubs;
using Aetheus.Back.Services.DomainEvents;
using Microsoft.AspNetCore.SignalR;
using Microsoft.EntityFrameworkCore;
using NSubstitute;
using Environment = Aetheus.Back.Data.Entities.Environment;

namespace Aetheus.Back.IntegrationTests;

/// <summary>
/// Recette R-60 on a real PostgreSQL, through the real variable resolution, condition evaluation and approval gate: a
/// production deployment generated by the wizard asks for ONE approval per run, whichever of the two mechanisms is active
/// (the wizard's option, written as the pipeline variable the template's approval stage reads, and the project's production
/// environment requiring approval), and both together never ask twice.
/// </summary>
public sealed class PipelineProductionApprovalIntegrationTests(PostgresFixture fixture) : RelationalTestBase(fixture)
{
    private const string ApprovalCondition = "ne(variables['RELEASE_GATE_APPROVAL'], 'not-required')";
    private const string Version = "1.4.0";

    private static PipelineStageDefinition Stage(string name, string? environment = null, int? approvalMinutes = null,
        string? condition = null) => new()
        {
            Name = name,
            ExecutionRole = "deploy",
            Environment = environment,
            ApprovalTimeoutMinutes = approvalMinutes,
            Condition = condition
        };

    /// <summary>The stages of the generic deployment template that matter here: the approval stage the wizard's pipeline
    /// reads its variable for, then the deployment itself. No stage names an environment.</summary>
    private static readonly PipelineStageDefinition[] TemplateStages =
    [
        Stage("Approve the production deployment", approvalMinutes: 60, condition: ApprovalCondition),
        Stage("Deploy")
    ];

    private sealed record Seed(int ProjectId, int RunId);

    private async Task<Seed> SeedAsync(bool environmentRequiresApproval, AnalysisGrade grade = AnalysisGrade.A)
    {
        await ResetAndMigrateAsync();
        var ct = TestContext.Current.CancellationToken;
        await using var db = NewContext();
        var organization = new Organization { Name = "Approvals", Slug = $"approvals-{Guid.NewGuid():N}"[..20] };
        db.Organizations.Add(organization);
        await db.SaveChangesAsync(ct);
        var project = new Project { Name = "Atlas", OrganizationId = organization.Id };
        db.Projects.Add(project);
        await db.SaveChangesAsync(ct);
        db.Environments.Add(new Environment { Name = "prod", ProjectId = project.Id, RequireApproval = environmentRequiresApproval });
        db.Releases.Add(new Release
        {
            ProjectId = project.Id,
            Version = Version,
            Deployable = true,
            AssuranceGrade = grade,
            DetectedAt = new DateTime(2026, 11, 3, 10, 0, 0, DateTimeKind.Utc)
        });
        var pipeline = new Pipeline { ProjectId = project.Id, Name = "atlas-deploy-prod", YamlDefinition = "name: atlas-deploy-prod\nstages: []" };
        db.Pipelines.Add(pipeline);
        await db.SaveChangesAsync(ct);
        var run = new PipelineRun { PipelineId = pipeline.Id, Status = PipelineStatus.Running, StartedAt = DateTime.UtcNow };
        db.PipelineRuns.Add(run);
        await db.SaveChangesAsync(ct);
        return new Seed(project.Id, run.Id);
    }

    private static PipelineRepository Repository(AppDbContext db) => new(
        db, TimeProvider.System,
        Microsoft.Extensions.Logging.Abstractions.NullLogger<PipelineRepository>.Instance,
        new Aetheus.Back.Components.Tasks.PipelineTaskLifecycleRepository(db, TimeProvider.System),
        new PipelineRunLineageRepository(db));

    private static PipelineStageApprovalGate Gate(PipelineRepository repo) =>
        new(repo, Substitute.For<IHubContext<PipelineHub>>(), Substitute.For<IDomainEventDispatcher>(), TimeProvider.System);

    /// <summary>The variables of the run as the engine writes them: the pipeline's own, then the release verdict.</summary>
    private static async Task<Dictionary<string, string>> VariablesAsync(
        PipelineRepository repo, int projectId, string? option, IReadOnlyList<PipelineStageDefinition> stages)
    {
        var definition = new PipelineYamlDefinition
        {
            Name = "atlas-deploy-prod",
            Trigger = "manual",
            Parameters = [new PipelineTemplateParameterDefinition { Name = "candidateVersion", Required = true }],
            Stages = [.. stages]
        };
        var resolved = new Dictionary<string, string>
        {
            [PipelineCommandBuilder.ParameterKeyPrefix + "candidateVersion"] = Version
        };
        if (option is not null) resolved[PipelineReleaseGateVariables.RequireApprovalVariable] = option;
        await PipelineReleaseGateVariables.InjectAsync(resolved, definition, projectId, repo, TestContext.Current.CancellationToken);
        return resolved;
    }

    /// <summary>Walks the run through its stages as the dispatcher does and returns what the gate decided, the approvals
    /// the run holds when it ends, and whether a stage was held at least once (the run waited for a decision).</summary>
    private async Task<List<PipelineApproval>> RunAsync(
        Seed seed, string? option, IReadOnlyList<PipelineStageDefinition> stages, bool environmentApprovedAtLaunch)
    {
        var ct = TestContext.Current.CancellationToken;
        await using var db = NewContext();
        var repo = Repository(db);
        var gate = Gate(repo);
        var variables = await VariablesAsync(repo, seed.ProjectId, option, stages);

        // The launch: environment approvals of the environments the stages name, before any stage is dispatched.
        if (await gate.RequireLaunchApprovalsAsync(seed.RunId, seed.ProjectId, stages, ct) && environmentApprovedAtLaunch)
            await DecideAsync(db, seed.RunId, ApprovalScope.Environment, ct);

        foreach (var stage in stages)
        {
            var verdict = PipelineConditionEvaluator.Evaluate(stage.Condition, variables, previousStageFailed: false);
            Assert.Null(verdict.Error);
            if (!verdict.Met) continue;
            // The same stage is offered again on every dispatch pass: while it waits, no new approval is raised.
            if (await gate.CheckAndCreateApprovalAsync(seed.RunId, seed.ProjectId, stage.Name, stage, stages, ct))
            {
                Assert.True(await gate.CheckAndCreateApprovalAsync(seed.RunId, seed.ProjectId, stage.Name, stage, stages, ct));
                await DecideAsync(db, seed.RunId, null, ct);
                Assert.False(await gate.CheckAndCreateApprovalAsync(seed.RunId, seed.ProjectId, stage.Name, stage, stages, ct));
            }
        }

        return await db.PipelineApprovals.AsNoTracking().Where(a => a.PipelineRunId == seed.RunId).ToListAsync(ct);
    }

    /// <summary>Approves the run's pending approval (of <paramref name="scope"/> when given), and puts the run back to
    /// Running as the approval service does when it resumes it.</summary>
    private static async Task DecideAsync(AppDbContext db, int runId, ApprovalScope? scope, CancellationToken ct)
    {
        var pending = await db.PipelineApprovals
            .Where(a => a.PipelineRunId == runId && a.Status == ApprovalStatus.Pending && (scope == null || a.Scope == scope))
            .ToListAsync(ct);
        foreach (var approval in pending)
        {
            approval.Status = ApprovalStatus.Approved;
            approval.ResolvedAt = DateTime.UtcNow;
        }
        var run = await db.PipelineRuns.SingleAsync(r => r.Id == runId, ct);
        run.Status = PipelineStatus.Running;
        await db.SaveChangesAsync(ct);
    }

    [Theory]
    [InlineData("true", false)]
    [InlineData("true", true)]
    [InlineData("false", true)]
    [InlineData(null, true)]
    public async Task EachMechanismAlone_AsksOneApproval_AndBothTogetherStillAskOne(string? option, bool environmentRequires)
    {
        var seed = await SeedAsync(environmentRequires);

        var approvals = await RunAsync(seed, option, TemplateStages, environmentApprovedAtLaunch: false);

        var asked = Assert.Single(approvals);
        Assert.Equal(ApprovalScope.Pipeline, asked.Scope);
        Assert.Equal("Approve the production deployment", asked.StageName);
        Assert.Equal(ApprovalStatus.Approved, asked.Status);
    }

    [Theory]
    [InlineData("false")]
    [InlineData(null)]
    public async Task NeitherMechanismActive_AsksNothingForAnAcceptedAReleaseOnAHealthyProject(string? option)
    {
        var seed = await SeedAsync(environmentRequiresApproval: false);

        var approvals = await RunAsync(seed, option, TemplateStages, environmentApprovedAtLaunch: false);

        Assert.Empty(approvals);
    }

    [Fact]
    public async Task APipelineThatNamesTheEnvironmentOnItsStages_StaysOnTheEnvironmentApproval_AskedOnce()
    {
        // The environment mechanism on its own (the platform's own deployment names prod on every stage): one Environment
        // approval at launch, and the template's approval stage is not asked beside it for an accepted release graded A.
        var seed = await SeedAsync(environmentRequiresApproval: true);
        PipelineStageDefinition[] stages =
        [
            Stage("Approve the production deployment", environment: "prod", approvalMinutes: 60, condition: ApprovalCondition),
            Stage("Deploy", environment: "prod")
        ];

        var approvals = await RunAsync(seed, option: null, stages, environmentApprovedAtLaunch: true);

        var asked = Assert.Single(approvals);
        Assert.Equal(ApprovalScope.Environment, asked.Scope);
        Assert.Equal(ApprovalStatus.Approved, asked.Status);
    }
}
